parameters.text:
You are a job matching specialist. Analyze this resume against the job description for a Director/VP of Customer Success role.

Requirements:
- Job must be Director, VP, or Head level in Customer Success
- Must be with a US-based company
- Must be remote/hybrid eligible
- Prefer roles with $175K+ salary (if mentioned)

Rate the match 0-100 and write a compelling cover letter (2-3 paragraphs, no header/signature).

Job Description: {{ $('Extract Salary Info').item.json.description }}
Job Title: {{ $('Extract Salary Info').item.json.title }}
Company: {{ $('Extract Salary Info').item.json.company }}
Location: {{ $('Extract Salary Info').item.json.location }}
Salary Info: {{ $('Extract Salary Info').item.json.salaryRange || "Not specified" }}
My Resume: {{ $('Extract from File').item.json.text }}

Response format: {"score": 85, "coverLetter": "Your cover letter text here", "reasoning": "Brief explanation of score and why this role matches your background"}

=🎯 High-Match CS Leadership Role Found!

📋 Title: {{ $json.Title }}
🏢 Company: {{ $json.Company }}
📍 Location: {{ $json.Location }}
💰 Salary: {{ $json['Salary Info'] }}
⭐ Match Score: {{ $json.score }}

🔗 Apply: {{ $('Extract Salary Info').item.json.applyLink }}

💡 AI Reasoning: {{ $json['AI Reasoning'] }}

parameters.jsCode:
// Enhanced search URL for Director/VP Customer Success roles with salary filtering
let url = "https://www.linkedin.com/jobs/search/?f_TPR=r2592000"; // Last 30 days

const first = $input.first().json;

// Specific search for CS leadership roles
let keyword = "Director Customer Success OR VP Customer Success OR Vice President Customer Success OR Head Customer Success";
let location = "United States";
const remote = "Remote,Hybrid"; // Allow remote and hybrid
const salaryMin = "5"; // LinkedIn salary code for $175K+
const experienceLevel = "5,6"; // Director, Executive

// Override with sheet values if present
if (first.Keyword && first.Keyword.trim()) {
  keyword = first.Keyword.trim();
}
if (first.Location && first.Location.trim()) {
  location = first.Location.trim();
}

// Add keyword search
url += `&keywords=${encodeURIComponent(keyword)}`;

// Add location (US-based companies)
url += `&location=${encodeURIComponent(location)}`;
if (location.toLowerCase().includes("united states")) {
  url += "&geoId=103644278";
}

// Add salary filter ($175K+)
url += `&f_SB2=${salaryMin}`;

// Add experience levels (Director, Executive)
url += `&f_E=${experienceLevel}`;

// Add work type (Remote, Hybrid, On-site)
const wtCodes = remote.split(",").map(r => {
  const type = r.trim();
  if (type === "Remote") return "2";
  if (type === "Hybrid") return "3";
  if (type === "On-Site") return "1";
  return "";
}).filter(Boolean).join(",");

if (wtCodes) {
  url += `&f_WT=${wtCodes}`;
}

// Easy apply preference
url += "&f_EA=true";

// Force server-side rendering to avoid JS detection
url += "&refresh=true";

console.log("Generated LinkedIn Search URL:", url);

return { url };

// Enhanced CS leadership filter, resilient US check
const includeCS = /\b(customer|client)\s+success\b/i;
const includeCX = /\bcustomer\s+experience\b/i;
const leadership = /\b(head|director|vp|vice\s*president)\b/i;

// Exclusions
const exclude = /\b(engineer|engineering|developer|architect|integration|devops|security|platform|data|ml|machine\s*learning|ai|infra|sre|qa|product\s+manager|sales\s+engineer|account\s+manager|support|intern|coordinator|specialist|analyst|associate(?!.*director))\b/i;

// State abbreviations, basic coverage
const US_STATES = /\b(AL|AK|AZ|AR|CA|CO|CT|DE|FL|GA|HI|ID|IL|IN|IA|KS|KY|LA|ME|MD|MA|MI|MN|MS|MO|MT|NE|NV|NH|NJ|NM|NY|NC|ND|OH|OK|OR|PA|RI|SC|SD|TN|TX|UT|VT|VA|WA|WV|WI|WY)\b/i;

const out = $input.all().filter(item => {
  const t = String(item.json?.title || "");
  const d = String(item.json?.description || "");
  const company = String(item.json?.company || "").toLowerCase();
  const locRaw = String(item.json?.location || "").trim();
  const loc = locRaw.toLowerCase();

  const csLike = includeCS.test(t) || includeCX.test(t) || includeCS.test(d);
  const isLeadership = leadership.test(t);
  const notExcluded = !exclude.test(t);

  // If LinkedIn occasionally sets location equal to company, treat as unknown rather than failing
  const locLooksBad = !loc || loc === company;

  // Heuristics for US
  const usFromLoc = /united states|usa|\bus\b|america|remote|hybrid/.test(loc) || US_STATES.test(loc);
  const usFromDesc = /united states|usa|\bus\b/.test(d.toLowerCase()) || US_STATES.test(d);
  const usFromSalary = /\$\s?\d/.test(String(item.json?.salaryInfo || ""));

  const passUS = usFromLoc || usFromDesc || usFromSalary || locLooksBad;

  return csLike && isLeadership && notExcluded && passUS;
});

return out;

// Reduced pagination to avoid rate limits
const base = $input.first().json.url;
const starts = Array.from({length: 5}, (_,i) => i*25); // Reduced to 5 pages to avoid rate limits
return starts.map(n => ({ json: { url: `${base}&start=${n}` } }));

// Flatten and deduplicate job links
const all = $input.all().flatMap(i => i.json.links || []);
// Enhanced deduplication
const uniq = Array.from(new Set(all.map(link => {
  // Normalize LinkedIn URLs
  if (link.includes('/jobs/view/')) {
    const jobId = link.match(/\/jobs\/view\/(\d+)/)?.[1];
    return jobId ? `https://www.linkedin.com/jobs/view/${jobId}` : link;
  }
  return link;
})));

console.log(`Found ${uniq.length} unique job links`);
return [{ json: { links: uniq } }];
